(function( $ ) {
	'use strict';

	$(document).ready(function() {
		$('body').on('click', '.ka4wp-upload-file', function(event) {
			event.preventDefault();

			const button = $(this);
			const imageId = button.next().next().val();
			const customUploader = wp.media({
				title: lang.insert_image,
				library: {
					type: 'image'
				},
				button: {
					text: lang.use_image
				},
				multiple: false
			}).on('select', function() {
				const attachment = customUploader.state().get('selection').first().toJSON();
				button.removeClass('button').html('<img src="' + attachment.url + '">');
				button.next().removeClass('d-none');
				button.next().next().val(attachment.id);
			});

			customUploader.on('open', function() {
				if (imageId) {
					const selection = customUploader.state().get('selection');
					const attachment = wp.media.attachment(imageId);
					attachment.fetch();
					selection.add(attachment ? [attachment] : []);
				}
			});

			customUploader.open();
		});

		$('body').on('click', '.ka4wp-remove-file', function(event) {
			event.preventDefault();
			const button = $(this);
			button.next().val('');
			button.addClass('d-none').prev().addClass('button').html(lang.upload_image);
		});
	});
})( jQuery );
